</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 410;
const int MAXM = 200020;
const int INF = 0x3f3f3f3f;
const int dirX[4] = {-1, 0, 1, 0};
const int dirY[4] = {0, 1, 0, -1};

int first[MAXN], to[MAXM], nxtE[MAXM], capacity[MAXM], curFlow[MAXM], edgeCnt;
int level[MAXN], arc[MAXN];
int source, sink;

void initGraph() {
    memset(first, -1, sizeof(first));
    edgeCnt = 0;
}

void addEdge(int u, int v, int c) {
    to[edgeCnt] = v;
    nxtE[edgeCnt] = first[u];
    capacity[edgeCnt] = c;
    curFlow[edgeCnt] = 0;
    first[u] = edgeCnt++;

    to[edgeCnt] = u;
    nxtE[edgeCnt] = first[v];
    capacity[edgeCnt] = 0;
    curFlow[edgeCnt] = 0;
    first[v] = edgeCnt++;
}

bool buildLevels() {
    memset(level, -1, sizeof(level));
    queue<int> q;
    level[source] = 0;
    q.push(source);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int e = first[u]; e != -1; e = nxtE[e]) {
            int v = to[e];
            if (level[v] == -1 && capacity[e] > curFlow[e]) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[sink] != -1;
}

int sendFlow(int u, int pushed) {
    if (u == sink || pushed == 0) return pushed;
    int sent = 0;
    for (int &e = arc[u]; e != -1; e = nxtE[e]) {
        int v = to[e];
        if (level[v] == level[u] + 1 && capacity[e] > curFlow[e]) {
            int tmp = sendFlow(v, min(pushed, capacity[e] - curFlow[e]));
            if (tmp > 0) {
                curFlow[e] += tmp;
                curFlow[e ^ 1] -= tmp;
                pushed -= tmp;
                sent += tmp;
                if (pushed == 0) break;
            }
        }
    }
    return sent;
}

int maxflow(int s, int t) {
    source = s;
    sink = t;
    int ans = 0;
    while (buildLevels()) {
        memcpy(arc, first, sizeof(first));
        ans += sendFlow(source, INF);
    }
    return ans;
}

int tim[12][12], dis[12][12];
char g[MAXN][MAXN], h[MAXN][MAXN];
int n, limitT;

bool inside(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void bfs1(int sx, int sy) {
    memset(tim, 0x3f, sizeof(tim));
    queue<int> q;
    q.push(sx * 10 + sy);
    tim[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dirX[k], ny = y + dirY[k];
            if (inside(nx, ny) && g[nx][ny] >= '0' && g[nx][ny] <= '9' && tim[nx][ny] > tim[x][y] + 1) {
                tim[nx][ny] = tim[x][y] + 1;
                q.push(nx * 10 + ny);
            }
        }
    }
}

void bfs2(int sx, int sy) {
    memset(dis, 0x3f, sizeof(dis));
    queue<int> q;
    q.push(sx * 10 + sy);
    dis[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front() / 10, y = q.front() % 10;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dirX[k], ny = y + dirY[k];
            if (inside(nx, ny) && h[nx][ny] >= '0' && h[nx][ny] <= '9' && dis[nx][ny] > dis[x][y] + 1) {
                if (tim[nx][ny] >= dis[x][y] + 1) {
                    dis[nx][ny] = dis[x][y] + 1;
                    if (tim[nx][ny] > dis[nx][ny])
                        q.push(nx * 10 + ny);
                }
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &limitT);
    for (int i = 0; i < n; ++i) scanf("%s", g[i]);
    for (int i = 0; i < n; ++i) scanf("%s", h[i]);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (g[i][j] == 'Z')
                bfs1(i, j);

    int S = 0, T = n * n * 2 + 1;
    initGraph();

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (g[i][j] > '0' && g[i][j] <= '9')
                addEdge(S, i * n + j + 1, g[i][j] - '0');
            if (h[i][j] > '0' && h[i][j] <= '9')
                addEdge(n * n + i * n + j + 1, T, h[i][j] - '0');
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (g[i][j] > '0' && g[i][j] <= '9') {
                bfs2(i, j);
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (h[x][y] > '0' && h[x][y] <= '9' && dis[x][y] <= limitT)
                            addEdge(i * n + j + 1, n * n + x * n + y + 1, INF);
            }

    printf("%d\n", maxflow(S, T));
    return 0;
}
